import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"项目实战总览","description":"","frontmatter":{"title":"项目实战总览"},"headers":[],"relativePath":"frontend/practices/index.md","filePath":"frontend/practices/index.md","lastUpdated":1785666337000}'),o={name:"frontend/practices/index.md"};function n(i,t,h,l,c,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="项目实战总览" tabindex="-1">项目实战总览 <a class="header-anchor" href="#项目实战总览" aria-label="Permalink to &quot;项目实战总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>项目实战用于把分散知识组合成完整交付。每个案例都从业务目标和约束出发，覆盖需求拆解、架构设计、关键实现、质量验证、上线运行和复盘，而不是只展示最终代码。</p><p>实战项目不追求复制一个固定模板。相同技术在团队规模、数据量、实时性、兼容性和交付周期不同的情况下，可能产生完全不同的设计。</p><h2 id="实战地图" tabindex="-1">实战地图 <a class="header-anchor" href="#实战地图" aria-label="Permalink to &quot;实战地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>项目类型</th><th>主要训练目标</th></tr></thead><tbody><tr><td><a href="/frontend/practices/methodology">项目落地方法</a></td><td>贯穿案例、需求验收、方案评审、风险验证、上线复盘</td><td>跟随一个前端需求完成从澄清到生产验证的全过程</td></tr><tr><td><a href="/frontend/practices/framework/react-project">框架项目实践</a></td><td>React 19 与 Vue 3 工程实践</td><td>将框架 API、生态、目录和工程约束组合起来</td></tr><tr><td><a href="/frontend/practices/solutions/">方案实践</a></td><td>高频、跨模块的前端问题</td><td>将知识、工程约束与技术决策组合成可落地方案</td></tr><tr><td><a href="/frontend/practices/enterprise-admin">业务应用</a></td><td>中后台、SSR、协同和 AI 助手</td><td>处理状态、权限、数据流、实时性与交互复杂度</td></tr><tr><td><a href="/frontend/practices/component-library">基础设施</a></td><td>组件库、监控 SDK 和工程平台</td><td>设计稳定 API、工具链和多团队复用机制</td></tr><tr><td><a href="/frontend/practices/schema-low-code">平台型项目</a></td><td>低代码与微前端平台</td><td>处理扩展性、隔离、协议和平台治理</td></tr><tr><td><a href="/frontend/practices/performance-governance">治理与迁移</a></td><td>性能治理与遗留系统迁移</td><td>在持续交付中改造已有大型系统</td></tr></tbody></table><h2 id="一个完整案例应包含什么" tabindex="-1">一个完整案例应包含什么 <a class="header-anchor" href="#一个完整案例应包含什么" aria-label="Permalink to &quot;一个完整案例应包含什么&quot;">​</a></h2><h3 id="_1-背景与约束" tabindex="-1">1. 背景与约束 <a class="header-anchor" href="#_1-背景与约束" aria-label="Permalink to &quot;1. 背景与约束&quot;">​</a></h3><p>明确用户、业务目标、规模、团队、周期、运行环境和不可接受的风险。没有约束的技术方案无法被评价。</p><h3 id="_2-问题拆解" tabindex="-1">2. 问题拆解 <a class="header-anchor" href="#_2-问题拆解" aria-label="Permalink to &quot;2. 问题拆解&quot;">​</a></h3><p>识别核心用例、领域边界、数据流、关键质量属性和最可能失败的部分，区分必须解决的问题与可以延后的问题。</p><h3 id="_3-方案与取舍" tabindex="-1">3. 方案与取舍 <a class="header-anchor" href="#_3-方案与取舍" aria-label="Permalink to &quot;3. 方案与取舍&quot;">​</a></h3><p>记录候选方案、选择标准和放弃项。需要说明为什么当前方案适合这个项目，而不是把技术栈名称当成设计结论。</p><h3 id="_4-关键实现" tabindex="-1">4. 关键实现 <a class="header-anchor" href="#_4-关键实现" aria-label="Permalink to &quot;4. 关键实现&quot;">​</a></h3><p>聚焦决定系统性质的部分，例如状态模型、模块边界、缓存一致性、实时协议、扩展接口、监控埋点或迁移适配层。</p><h3 id="_5-验证与运行" tabindex="-1">5. 验证与运行 <a class="header-anchor" href="#_5-验证与运行" aria-label="Permalink to &quot;5. 验证与运行&quot;">​</a></h3><p>通过测试、性能数据、安全检查、发布方案和生产监控验证目标。只有开发环境能够运行，不代表项目已经完成。</p><h3 id="_6-复盘与演进" tabindex="-1">6. 复盘与演进 <a class="header-anchor" href="#_6-复盘与演进" aria-label="Permalink to &quot;6. 复盘与演进&quot;">​</a></h3><p>比较预期与真实结果，记录技术债、失败尝试和下一阶段触发条件，让案例保留决策过程而不只是最终结构。</p><h2 id="推荐实践顺序" tabindex="-1">推荐实践顺序 <a class="header-anchor" href="#推荐实践顺序" aria-label="Permalink to &quot;推荐实践顺序&quot;">​</a></h2><p>先通过项目落地方法理解需求澄清、方案评审、风险验证、上线和复盘，再用框架项目实践建立完整交付基线；遇到明确的局部复杂问题时，选择对应的方案实践；之后完成一个具有真实约束的业务应用。具备稳定交付能力后，可以继续尝试组件库、监控 SDK 等基础设施，最后进入低代码、微前端、性能治理和遗留迁移等长期系统问题。</p><p>每个项目都应主动关联其他模块：使用<a href="/frontend/guide/core/">核心知识</a>解释实现，使用<a href="/frontend/guide/engineering/">工程体系</a>保障交付，按需调用<a href="/frontend/topics/">专题进阶</a>中的专项能力，使用<a href="/frontend/decisions/">技术决策</a>记录取舍，必要时进入<a href="/frontend/deep-dive/">原理深挖</a>验证底层假设。</p><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><ul><li>有明确的问题、约束和可验证目标，而不只是功能列表。</li><li>有可解释的系统边界、数据流和关键决策记录。</li><li>有与风险匹配的测试、性能、安全和发布验证。</li><li>有生产运行需要的监控、降级和恢复考虑。</li><li>有对失败、技术债和后续演进条件的复盘。</li></ul>',24)])])}const u=a(o,[["render",n]]);export{f as __pageData,u as default};
